import {usbSelection} from './usb-core.js';
import {THREE,Viewer,partModel,normalize,bounds,exportSTL} from './models.js';
import {profileFor,engineSettings,parseToolpaths,colorChanges,sliceTarget,applySliceEstimates} from './slicer-core.js';
import {esc,btn,field,select} from './views.js';
import * as storage from './storage.js';
export function slicerController(c){const {ui,render,persist,showModal,closeModal,toast}=c,S=c.state,$=id=>document.getElementById(id);let viewer=null,generation=0,polling=false,preparing=false,startPending=false,target=null,handledFile='',keyList=[];const printer=()=>S().printers.find(p=>p.id===S().activePrinterId),object=c.object;
 function dispose(){generation++;if(viewer?.group)viewer.group.traverse(m=>{if(m.isLineSegments||m.userData.plate){m.geometry?.dispose();m.material?.dispose();}});viewer?.dispose();viewer=null;}
 function bed(){const p=printer(),g=new THREE.Group(),mesh=new THREE.Mesh(new THREE.PlaneGeometry(p.bedX,p.bedY),new THREE.MeshBasicMaterial({color:'#547051',transparent:true,opacity:.12,side:THREE.DoubleSide}));mesh.position.z=-.1;mesh.userData.plate=true;g.add(mesh);const edge=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(p.bedX,p.bedY,.2)),new THREE.LineBasicMaterial({color:'#789666'}));g.add(edge);return g;}
 async function plate(){const p=printer(),o=object();if(!o?.parts.length)throw Error('Agrega modelos a la caja antes de laminar.');const sources=o.parts.filter(part=>!ui.slicePart||ui.slicePart==='all'||part.id===ui.slicePart),models=[];const cfg=profileFor(p),margin=Math.max(5,S().settings.margin||0,cfg.adhesion==='brim'?cfg.brim+2:cfg.adhesion==='raft'?10:5);let x=margin,y=margin,row=0;const count=ui.sliceCopies||1;if(!Number.isInteger(count)||count<1||count>100)throw Error('Usa entre 1 y 100 repeticiones.');
 for(const part of sources){const copies=count*(ui.slicePart&&ui.slicePart!=='all'?1:part.qty||1);for(let i=0;i<copies;i++){if(models.length>=100)throw Error('Máximo 100 mallas por cama.');const m=await partModel({...part,position:[0,0,0],rotation:o.sliceRotations?.[part.id]||[0,0,0]},S().materials,storage.getFile);normalize(m);const d=bounds(m);if(d[0]>p.bedX-2*margin||d[1]>p.bedY-2*margin||d[2]>p.bedZ)throw Error(`${part.name} no cabe en la cama con esta orientación.`);if(x+d[0]>p.bedX-margin){x=margin;y+=row+Math.max(4,S().settings.gap);row=0;}if(y+d[1]>p.bedY-margin)throw Error('No cabe todo en una cama. Reduce la cantidad o elige un componente.');m.position.x+=x+d[0]/2-p.bedX/2;m.position.y+=y+d[1]/2-p.bedY/2;m.updateMatrixWorld(true);models.push({name:part.name+'-'+i+'.stl',group:m,tool:o.toolAssignments?.[part.id]||0});x+=d[0]+Math.max(4,S().settings.gap);row=Math.max(row,d[1]);}}
 return models;
 }
 function pathsGroup(){const p=printer(),g=bed(),data=ui.sliceAnalysis||{paths:[]},buckets=new Map();for(const path of data.paths){if(path.layer>(ui.sliceLayer||1))continue;const key=path.extrude?path.tool:'travel',bucket=buckets.get(key)||[];for(const a of [path.from,path.to])bucket.push(a[0]-p.bedX/2,a[1]-p.bedY/2,a[2]);buckets.set(key,bucket);}const colors=['#6caa69','#cb8052','#c5b67f','#829fc0','#d18cad','#92bca9','#caa342','#9795cf'];for(const [key,coords] of buckets){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(coords,3));g.add(new THREE.LineSegments(geo,new THREE.LineBasicMaterial({color:key==='travel'?'#92a28c':colors[key%colors.length],transparent:true,opacity:key==='travel'?.15:.95})));}return g;}
 async function mount(){if(ui.view!=='slicer')return;const el=$('slice-viewer'),token=generation,enter=!!ui.animateObject,direction=ui.objectDirection||1;if(!el)return;try{const g=ui.sliceMode==='paths'&&ui.sliceText?pathsGroup():bed();if(ui.sliceMode!=='paths'||!ui.sliceText)for(const model of await plate())g.add(model.group);if(token!==generation)return;viewer=new Viewer(el);viewer.grid.visible=false;viewer.set(g,{animate:enter,direction});}catch(e){if(token===generation)el.innerHTML=`<div class="viewer-error"><span>${esc(e.message)}</span></div>`;}updatePrint();}
 const changes=()=>object()?.colorChanges||ui.colorChanges||[];
 function setText(text,name,base=true){if(base){ui.sliceBase=text;ui.sliceName=name;ui.colorChanges=[];if(object())object().colorChanges=[];}ui.sliceText=text;ui.sliceAnalysis=parseToolpaths(text);ui.sliceLayer=ui.sliceAnalysis.maxLayer;ui.sliceMode='paths';}
 function reapply(){if(!ui.sliceBase)throw Error('Carga o lamina primero un archivo.');const edited=colorChanges(ui.sliceBase,changes(),printer());setText(edited,ui.sliceName,false);persist();render();}
 async function detect(pick=false,quiet=false){const mode=pick?'custom':S().settings.engineMode||'builtin',r=await storage.api('engine-info',{engine:mode==='custom'?S().settings.enginePath||'':'',mode,pick});if(r.canceled)return false;if(!r.engine)throw Error(mode==='builtin'?'No se pudo preparar el motor incluido. Reabre la app o selecciona un motor personalizado.':'No se encontró el motor personalizado. Selecciona CuraEngine.exe y sus definiciones.');S().settings.engineMode=mode;S().settings.enginePath=r.engine;if(r.definition)S().settings.engineDefinition=r.definition;if(r.extruderDefinition)S().settings.extruderDefinition=r.extruderDefinition;persist();if(!quiet){render();toast(mode==='builtin'?'Motor incluido 5.13.0 listo.':'Motor personalizado seleccionado.');}return true;}
 async function run(){if(preparing||ui.sliceRunning)return;preparing=true;try{const p=printer(),o=object(),jobTarget=sliceTarget(S(),c.box(),o,p,ui.slicePart||'all',ui.sliceCopies||1),settings=engineSettings(p,profileFor(p)),models=await plate();jobTarget.diameters=settings.extruders.map(e=>+e.material_diameter);if(S().settings.engineMode!=='custom'||!S().settings.enginePath||!S().settings.engineDefinition)await detect(false,true);if(!S().settings.enginePath||!S().settings.engineDefinition)throw Error('Completa las rutas del motor personalizado en Opciones avanzadas.');const data=new FormData();for(const m of models)data.append('models',exportSTL(m.group),m.name);const r=await fetch('/api/prepare',{method:'POST',headers:{'X-Woods-Request':'1'},body:data});if(!r.ok)throw Error(await r.text());const prepared=await r.json();await storage.api('slice-start',{engine:S().settings.enginePath,definition:S().settings.engineDefinition,extruderDefinition:S().settings.extruderDefinition,...settings,models:prepared.files.map((path,i)=>({path,tool:models[i].tool}))});target=jobTarget;ui.sliceRunning=true;ui.sliceLog='Iniciando motor local…';render();}finally{preparing=false;}}
 function selection(){return usbSelection(printer(),ui.devices||[],$('usb-manual-port')?.value||printer().usbPort);}
 function updatePrint(){const st=ui.printStatus||{},el=document.querySelector('[data-print-status]');if(st.state==='error'&&st.message)ui.printError=st.message;if(el)el.textContent=`${st.message||'Sin impresión activa'}${st.total?' · '+(100*(st.sent||0)/st.total).toFixed(1)+'% de comandos confirmados':''}`;const prog=document.querySelector('[data-print-progress]');if(prog)prog.value=st.total?100*(st.sent||0)/st.total:0;const error=$('usb-error');if(error){error.hidden=!ui.printError;error.textContent=ui.printError||'';}if($('usb-log'))$('usb-log').textContent=(ui.printError?ui.printError+'\n':'')+(st.log||'El intercambio USB aparecerá aquí.');for(const [action,enabled] of [['usb-pause',st.state==='printing'],['usb-resume',st.state==='paused'],['usb-stop',['checking','connecting','printing','paused','firmware-pause'].includes(st.state)],['test-usb',!startPending&&!['checking','connecting','printing','paused','firmware-pause'].includes(st.state)],['slice-print',!startPending&&!['checking','connecting','printing','paused','firmware-pause'].includes(st.state)]]){const button=document.querySelector(`[data-action="${action}"]`);if(button)button.disabled=!enabled;}const confirm=document.querySelector('[data-action="confirm-usb-print"]');if(confirm)confirm.disabled=startPending;}
 async function testUSB(){if(startPending||isPrinting()||ui.printStatus?.state==='checking')throw Error('Espera a que termine la conexión o impresión actual.');try{await c.probe?.();const connection=selection();ui.printError='';startPending=true;ui.printStatus={state:'checking',message:`Probando ${connection.port} a ${profileFor(printer()).baud} baudios…`};updatePrint();await storage.api('usb-test',{...connection,baud:profileFor(printer()).baud});render();}catch(e){ui.printError=e.message;ui.printStatus={...ui.printStatus,state:'error',message:e.message};updatePrint();throw e;}finally{startPending=false;updatePrint();}}
 async function poll(){if(polling||!storage.isNative)return;polling=true;try{const [slice,print]=await Promise.all([storage.api('slice-status'),storage.api('print-status')]);if(!startPending)ui.printStatus=print;updatePrint();if(ui.sliceRunning){ui.sliceLog=slice.log||'';if($('slice-log'))$('slice-log').textContent=ui.sliceLog;if($('slice-job-status'))$('slice-job-status').textContent=slice.state==='running'?'Laminando…':slice.state==='ready'?'Laminado terminado':'El laminado se detuvo';if(slice.state==='error'){ui.sliceRunning=false;render();toast('CuraEngine no pudo terminar. Revisa su registro.',true);}if(slice.state==='ready'&&slice.file&&slice.file!==handledFile){handledFile=slice.file;ui.sliceRunning=false;const text=await(await storage.getFile(slice.file)).text();if(target){const o=S().boxes.find(b=>b.id===target.boxId)?.objects.find(o=>o.id===target.objectId);if(o){o.lastSliceFile=slice.file;o.lastSlicePrinter=target.printerId;try{ui.sliceStats=applySliceEstimates(S(),target,text);}catch(e){toast(e.message,true);}const b=S().boxes.find(b=>b.id===target.boxId);if(b?.folder){try{const f=await storage.putFile(new File([text],o.name+'-laminado.gcode'),b);b.files.push(f);o.lastSliceFile=f.id;}catch(e){toast('El laminado está listo, pero no se pudo copiar a la caja: '+e.message,true);}}}}if(!target||(c.box()?.id===target.boxId&&object()?.id===target.objectId)){setText(text,'impresion.gcode');ui.slicePrinterId=target?.printerId;}persist();render();toast('Laminado listo. Revisa las capas antes de imprimir.');}}}catch(e){ui.printError=e.message;updatePrint();if(isPrinting()){ui.printStatus={...ui.printStatus,message:'No se pudo consultar el estado. Revisa la conexión con la app; no asumas que la impresión se detuvo.'};updatePrint();}}finally{polling=false;}}
 function isPrinting(){return startPending||['connecting','printing','paused','firmware-pause'].includes(ui.printStatus?.state);}
 async function printDialog(){try{if(!ui.sliceText&&object()?.lastSliceFile)await actions['slice-load-last']();if(!ui.sliceText)throw Error('Primero pulsa Laminar esta cama o abre un G-code. Después podrás revisar y enviar la impresión.');const p=printer();if(ui.slicePrinterId&&ui.slicePrinterId!==p.id)throw Error('Este G-code pertenece a otro perfil de impresora. Elige ese perfil o vuelve a laminar para el actual.');await c.probe?.();const connection=selection();ui.printError='';updatePrint();showModal('Revisar impresión por USB',`<div class="panel"><b>${esc(p.printer)}</b><p>${esc(connection.port)} · ${profileFor(p).baud} baudios<br>${esc(ui.sliceName)} · ${ui.sliceAnalysis?.maxLayer||0} capas</p></div><p class="section-space">Revisa material, boquilla, temperaturas y cama. Al confirmar se consultará el firmware y se enviará el G-code. La impresora puede reiniciarse al abrir USB.</p><label class="field inline"><input type="checkbox" id="print-reviewed"> Revisé el perfil, las capas y la impresora física</label>`,btn('Cancelar','close-modal')+btn('Iniciar impresión USB','confirm-usb-print','printer','primary'));}catch(e){ui.printError=e.message;ui.printStatus={...ui.printStatus,state:'error',message:e.message};updatePrint();throw e;}}
 function keysMarkup(term=''){const filtered=keyList.filter(k=>(k.key+' '+k.label).toLowerCase().includes(term.toLowerCase()));return `<p class="short-note">${filtered.length} ajustes · se muestran hasta 100 coincidencias.</p>${filtered.slice(0,100).map(k=>`<div class="cost-row"><span><b>${esc(k.key)}</b><br>${esc(k.label)} · ${esc(JSON.stringify(k.default))}</span>${btn('Configurar','edit-engine-key','edit','small',`data-key="${esc(k.key)}"`)}</div>`).join('')}`;}
 const actions={
 'slice-run':run,'slice-load-last':async()=>{const o=object();if(!o?.lastSliceFile)throw Error('Este objeto no tiene un laminado guardado.');const saved=structuredClone(o.colorChanges||[]);setText(await(await storage.getFile(o.lastSliceFile)).text(),'impresion.gcode');ui.slicePrinterId=o.lastSlicePrinter;o.colorChanges=saved;ui.sliceStats=o.lastSliceStats;reapply();},'detect-engine':()=>detect(),'pick-engine':()=>detect(true),'slice-cancel':async()=>{await storage.api('slice-cancel',{});},
 'slice-models':()=>{ui.sliceMode='models';render();},'slice-paths':()=>{ui.sliceMode='paths';render();},'slice-fit':()=>viewer?.fit(),
 'slice-import':()=>{const input=$('file-input');input.accept='.gcode,.gco';input.dataset.mode='slicer';input.click();},
 'slice-export':async()=>{if(!ui.sliceText)throw Error('No hay G-code preparado.');if(ui.sliceText.includes(';WOODS_HOST_PAUSE'))throw Error('Las pausas USB necesitan 3D-Woods. Para exportar a SD cambia esas pausas a M600 o M0 compatibles con tu firmware.');await storage.download(new Blob([ui.sliceText],{type:'text/plain'}),(ui.sliceName||'impresion.gcode').replace(/\.gcode$/i,'')+'-woods.gcode');},
 'slice-estimates':()=>{if(ui.sliceText.includes(';WOODS_COLOR_CHANGE'))toast('El encabezado conserva las estimaciones anteriores a los cambios de color. Revisa por separado purgas, tiempos de pausa y reparto por material.');return c.readGcode(new File([ui.sliceText],ui.sliceName||'impresion.gcode'));},
 'add-color-change':()=>{const entry={layer:+$('color-layer').value,mode:$('color-mode').value,tool:+$('color-tool').value},next=[...changes(),entry];colorChanges(ui.sliceBase,next,printer());if(object())object().colorChanges=next;else ui.colorChanges=next;reapply();},
 'remove-color-change':el=>{const next=changes().filter((_,i)=>i!==+el.dataset.index);if(object())object().colorChanges=next;else ui.colorChanges=next;reapply();},
 'slice-print':printDialog,
 'test-usb':testUSB,
 'export-usb-diagnostic':async()=>{const st=ui.printStatus||{},text=['3D-Woods · Diagnóstico USB',new Date().toISOString(),'Perfil: '+printer().printer,'Puerto: '+(st.port||printer().usbPort||printer().deviceId||'Sin seleccionar'),'Baudios: '+profileFor(printer()).baud,'Estado: '+(st.state||'idle'),ui.printError||st.message||'',st.firmware||'',st.log||''].join('\r\n');await storage.download(new Blob([text],{type:'text/plain;charset=utf-8'}),'3D-Woods-diagnostico-USB.txt');},
 'confirm-usb-print':async()=>{if(!$('print-reviewed').checked)throw Error('Revisa la impresión y marca la confirmación.');if(startPending||isPrinting()||ui.printStatus?.state==='checking')throw Error('Ya hay una conexión o impresión activa.');const connection=selection();startPending=true;ui.printError='';ui.printStatus={state:'connecting',message:`Abriendo ${connection.port}…`};updatePrint();try{const r=await storage.api('print-start',{...connection,text:ui.sliceText,name:ui.sliceName,baud:profileFor(printer()).baud});if(r.started){closeModal();render();}}catch(e){ui.printError=e.message;ui.printStatus={...ui.printStatus,state:'error',message:e.message};updatePrint();throw e;}finally{startPending=false;updatePrint();}},
 'usb-pause':()=>storage.api('print-control',{action:'pause'}),'usb-resume':()=>storage.api('print-control',{action:'resume'}),
 'usb-stop':()=>ui.printStatus?.state==='checking'?storage.api('print-control',{action:'stop'}):showModal('Detener la impresión','<p>Se interrumpirá el envío y se solicitará M112. La pieza quedará incompleta. Verifica la parada en la impresora; puede requerir reinicio.</p>',btn('Volver','close-modal')+btn('Detener ahora','confirm-usb-stop','close','danger')),
 'confirm-usb-stop':async()=>{await storage.api('print-control',{action:'stop'});closeModal();toast('Parada solicitada. Verifica la impresora.');},
 'engine-keys':async()=>{if(S().settings.engineMode!=='custom'||!S().settings.engineDefinition)await detect(false,true);const r=await storage.api('engine-keys',{path:S().settings.engineDefinition});keyList=r.keys;showModal('Opciones del motor local',`${field('Buscar ajuste','','id="engine-key-search"','text')}<div id="engine-key-list">${keysMarkup()}</div>`,btn('Cerrar','close-modal'));},
 'edit-engine-key':el=>{const k=keyList.find(k=>k.key===el.dataset.key),advanced=JSON.parse(profileFor(printer()).advanced||'{}'),v=(advanced.global||advanced)[k.key]??k.default;showModal(k.label||k.key,`${field(k.key,typeof v==='object'?JSON.stringify(v):String(v??''),'id="engine-key-value"','text')}<p>Introduce un valor resuelto. No se evalúan expresiones ni fórmulas de Cura.</p>`,btn('Cancelar','close-modal')+btn('Aplicar ajuste','save-engine-key','check','primary',`data-key="${esc(k.key)}"`));},
 'save-engine-key':el=>{const config=profileFor(printer()),advanced=JSON.parse(config.advanced||'{}');let value=$('engine-key-value').value;try{value=JSON.parse(value);}catch{}if(advanced.global)advanced.global[el.dataset.key]=value;else advanced[el.dataset.key]=value;config.advanced=JSON.stringify(advanced,null,2);closeModal();persist();render();}
 };
 async function change(el){if(el.id==='slice-box'){c.changeObject(()=>{ui.selected=el.value;ui.objectId=null;ui.slicePart='all';ui.sliceMode='models';ui.sliceText=null;ui.sliceBase=null;ui.slicePrinterId=null;});return true;}if(el.id==='slice-object'){c.changeObject(()=>{ui.objectId=el.value;ui.slicePart='all';ui.sliceMode='models';ui.sliceText=null;ui.sliceBase=null;ui.slicePrinterId=null;});return true;}if(el.id==='slice-part'||el.id==='slice-copies'){if(el.type==='number'&&!el.checkValidity())throw Error('Revisa la cantidad.');ui[el.id==='slice-part'?'slicePart':'sliceCopies']=el.id==='slice-part'?el.value:+el.value;ui.sliceMode='models';render();return true;}
 if(el.id==='slice-layer'||el.id==='slice-layer-range'){ui.sliceLayer=Math.max(1,Math.min(ui.sliceAnalysis?.maxLayer||1,+el.value||1));ui.sliceMode='paths';dispose();render();return true;}
 if(el.dataset.sliceSetting){if(el.type==='number'&&!el.checkValidity())throw Error('Revisa el ajuste de laminado.');const key=el.dataset.sliceSetting,config=profileFor(printer());config[key]=el.type==='checkbox'?el.checked:el.type==='number'||key==='baud'?+el.value:el.value;persist();if(['tools','autoTools'].includes(key))render();return true;}
 if(el.id==='engine-mode'){S().settings.engineMode=el.value;persist();render();return true;}
 if(el.dataset.toolMaterial!=null){const config=profileFor(printer());config.materials??={};config.materials[el.dataset.toolMaterial]=el.value;persist();return true;}
 if(el.dataset.enginePath){S().settings[el.dataset.enginePath]=el.value.trim();persist();return true;}
 if(el.id==='slice-device'){const p=printer();p.usbManual=el.value==='__manual__';if(!p.usbManual){p.deviceId=el.value;p.usbPort=(ui.devices||[]).find(d=>d.id===el.value)?.port||'';}p.connection='usb';ui.printError='';persist();render();return true;}
 if(el.id==='usb-manual-port'){printer().usbPort=el.value.trim().toUpperCase();ui.printError='';persist();updatePrint();return true;}
 if(el.id==='slice-printer'){if(isPrinting()||ui.printStatus?.state==='checking')throw Error('Espera a que termine la operación USB antes de cambiar de impresora.');c.usePrinter(el.value);render();return true;}
 if(el.dataset.sliceTool){const o=object();o.toolAssignments??={};o.toolAssignments[el.dataset.sliceTool]=+el.value;persist();return true;}
 if(el.dataset.sliceRotation){if(!el.checkValidity())throw Error('Revisa el giro de impresión.');const o=object();o.sliceRotations??={};o.sliceRotations[el.dataset.sliceRotation]??=[0,0,0];o.sliceRotations[el.dataset.sliceRotation][+el.dataset.axis]=+el.value;ui.sliceMode='models';persist();render();return true;}
 return false;}
 document.addEventListener('input',e=>{if(e.target.id==='engine-key-search')$('engine-key-list').innerHTML=keysMarkup(e.target.value);});
 return {actions,change,mount,dispose,poll,isPrinting,isBusy:()=>preparing||ui.sliceRunning||startPending||ui.printStatus?.state==='checking',importFile:async file=>{if(file.size>25*1024*1024)throw Error('El editor de G-code admite hasta 25 MB.');setText(await file.text(),file.name);ui.slicePrinterId=null;ui.sliceStats=null;ui.view='slicer';render();}};
}
